def subtract(a, b):
    def merge_intervals(intervals):
        if not intervals:
            return []

        # Filter out empty intervals and sort by start
        valid = [iv for iv in intervals if iv[0] < iv[1]]
        if not valid:
            return []

        valid.sort()
        merged = [valid[0]]

        for start, end in valid[1:]:
            if start <= merged[-1][1]:
                # Overlapping or touching, merge
                merged[-1][1] = max(merged[-1][1], end)
            else:
                # Disjoint, add new interval
                merged.append([start, end])

        return merged

    # Merge intervals in both a and b
    a_merged = merge_intervals(a)
    b_merged = merge_intervals(b)

    if not a_merged:
        return []

    result = []

    for a_start, a_end in a_merged:
        current = a_start

        for b_start, b_end in b_merged:
            if b_end <= current or b_start >= a_end:
                # b interval doesn't overlap with current position
                continue

            # b interval overlaps
            if current < b_start:
                # Add the part before b starts
                result.append([current, b_start])

            # Move current past b interval
            current = max(current, b_end)

        # Add remaining part of a after all b intervals
        if current < a_end:
            result.append([current, a_end])

    return result

